// mulberry32 — 작은 시드 기반 난수(같은 시드 = 같은 수열)
function seeded(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;   // 0~1
  };
}
const rand = seeded(8471);   // 시드 고정 → 재현 가능
// 시드를 화면에 표시하거나 저장에 담아라
// "가끔 이상해요" → "시드 8471 에서 이상해요" = 문제의 절반이 풀림

// ❌ 예측 가능 — 비밀번호 초기화 토큰·세션 id 에 쓰면 사고
Math.random().toString(36).slice(2);

// ✅ 암호학적 난수(CSPRNG) — 예측 불가
crypto.randomUUID();                          // 표준 UUID v4
crypto.getRandomValues(new Uint8Array(16));   // 16바이트(128비트)
// Node:  crypto.randomBytes(16).toString('hex')
// Python: secrets.token_urlsafe(32)
// 규칙: "추측하면 안 되는 값" 은 반드시 암호학적 난수로(128비트+)

// 1~6 주사위
Math.floor(Math.random() * 6) + 1;   // ✅ 0~5 균등 → +1
Math.round(Math.random() * 5) + 1;   // ✗ 양 끝(1·6)이 절반 확률(편향)

// 모듈로 편향 — 범위가 n 의 배수가 아니면 작은 값이 더 자주
randomInt(0, 255) % 6;   // ✗ 0~3 이 4~5 보다 살짝 많음

// 균등이 중요하면 거부 표집(rejection sampling)
function unbiased(n) {
  const max = Math.floor(4294967296 / n) * n;   // n 의 배수 상한
  let x; do { x = crypto.getRandomValues(new Uint32Array(1))[0]; } while (x >= max);
  return x % n;   // 범위 밖은 버리고 다시 → 편향 없음
}

// ❌ 난수를 직접 호출 — 테스트가 비결정적
function dropLoot() {
  return Math.random() < 0.2 ? 'rare' : 'common';   // 테스트 못 함
}

// ✅ 난수 함수를 인자로 받는다(주입)
function dropLoot(rand = Math.random) {
  return rand() < 0.2 ? 'rare' : 'common';
}
// 테스트: 고정 값을 돌려주는 함수를 넣으면 결정적
dropLoot(() => 0.1);   // 항상 'rare'
dropLoot(() => 0.9);   // 항상 'common'
